type IconName = ComponentProps<typeof Ionicons>["name"];
type Period = "7 дней" | "Месяц" | "3 месяца" | "Год";
type Route = { name: "overview" | "composition" | "segments" | "history" | "device" } | { name: "metric"; metric: Metric };
type Measurement = { id: string; recordedAt: string; readings: Map<Metric, DeviceReading> };
type ScaleMetricInfo = { metric: Metric; label: string; shortLabel: string; unit: string; digits: number; icon: IconName; color: string; soft: string; description: string };

const scale = deviceGateway.forKind("scale");
const AnimatedPath = Animated.createAnimatedComponent(Path);
const periodOptions: ReadonlyArray<{ value: Period; label: string }> = [
  { value: "7 дней", label: "7 дней" },
  { value: "Месяц", label: "Месяц" },
  { value: "3 месяца", label: "3 месяца" },
  { value: "Год", label: "Год" }
];
const metricCatalog: ReadonlyArray<ScaleMetricInfo> = [
  { metric: "weight", label: "Вес", shortLabel: "Вес", unit: "кг", digits: 2, icon: "scale-outline", color: axColors.green, soft: axColors.greenSoft, description: "Устойчивый вес, непосредственно полученный от AxMed Scale." },
  { metric: "bodyFatPercentage", label: "Процент жира", shortLabel: "Жир", unit: "%", digits: 1, icon: "flame-outline", color: axColors.coral, soft: axColors.coralSoft, description: "Расчётная доля жировой ткани. Оценивайте изменение в контексте общей динамики." },
  { metric: "muscleMass", label: "Мышечная масса", shortLabel: "Мышцы", unit: "кг", digits: 1, icon: "barbell-outline", color: axColors.blue, soft: axColors.blueSoft, description: "Расчётная мышечная масса по данным состава тела." },
  { metric: "bodyWaterPercentage", label: "Вода в организме", shortLabel: "Вода", unit: "%", digits: 1, icon: "water-outline", color: "#444444", soft: "#F8F8F8", description: "Расчётная доля воды; показатель естественно меняется в течение дня." },
  { metric: "proteinPercentage", label: "Белок", shortLabel: "Белок", unit: "%", digits: 1, icon: "nutrition-outline", color: axColors.amber, soft: axColors.amberSoft, description: "Расчётный показатель состава тела." },
  { metric: "visceralFatLevel", label: "Висцеральный жир", shortLabel: "Висц. жир", unit: "ур.", digits: 0, icon: "body-outline", color: axColors.coral, soft: axColors.coralSoft, description: "Расчётный индекс для наблюдения за динамикой." },
  { metric: "boneMass", label: "Костная масса", shortLabel: "Кости", unit: "кг", digits: 1, icon: "fitness-outline", color: axColors.purple, soft: axColors.purpleSoft, description: "Расчётная масса минеральной составляющей костной ткани." },
  { metric: "basalMetabolicRate", label: "Базовый обмен", shortLabel: "BMR", unit: "ккал", digits: 0, icon: "flash-outline", color: axColors.amber, soft: axColors.amberSoft, description: "Оценка энергии, расходуемой организмом в состоянии покоя." },
  { metric: "metabolicAge", label: "Метаболический возраст", shortLabel: "Возраст тела", unit: "лет", digits: 0, icon: "time-outline", color: axColors.green, soft: axColors.greenSoft, description: "Сравнительный расчётный показатель, а не медицинская оценка возраста." },
  { metric: "bodyScore", label: "Оценка тела", shortLabel: "Оценка", unit: "/ 100", digits: 0, icon: "sparkles-outline", color: axColors.purple, soft: axColors.purpleSoft, description: "Сводная демонстрационная оценка состава тела." },
  { metric: "heartRate", label: "Пульс", shortLabel: "Пульс", unit: "уд/мин", digits: 0, icon: "heart-outline", color: axColors.coral, soft: axColors.coralSoft, description: "Пульс во время измерения, если устройство передаёт этот канал." }
];
const metricByName = new Map(metricCatalog.map(item => [item.metric, item]));
const segmentCatalog: ReadonlyArray<{ key: BodySegmentKey; label: string; muscle: Metric; fat: Metric }> = [
  { key: "leftArm", label: "Левая рука", muscle: "leftArmMuscleMass", fat: "leftArmFatPercentage" },
  { key: "rightArm", label: "Правая рука", muscle: "rightArmMuscleMass", fat: "rightArmFatPercentage" },
  { key: "trunk", label: "Корпус", muscle: "trunkMuscleMass", fat: "trunkFatPercentage" },
  { key: "leftLeg", label: "Левая нога", muscle: "leftLegMuscleMass", fat: "leftLegFatPercentage" },
  { key: "rightLeg", label: "Правая нога", muscle: "rightLegMuscleMass", fat: "rightLegFatPercentage" }
];

function fmt(value: number | undefined, digits = 1) { return value === undefined ? "—" : value.toLocaleString("ru-RU", { minimumFractionDigits: digits > 0 ? 1 : 0, maximumFractionDigits: digits }); }
function dateLabel(value: string, timeZone?: string) { return new Date(value).toLocaleString("ru-RU", { ...(timeZone ? { timeZone } : {}), day: "numeric", month: "short", hour: "2-digit", minute: "2-digit" }); }
function makeMeasurements(samples: readonly DeviceReading[]) {
  const groups = new Map<string, Measurement>();
  for (const sample of samples) { const id = `${sample.sourceRecordId}:${sample.recordedAt}`; const group = groups.get(id) ?? { id, recordedAt: sample.recordedAt, readings: new Map<Metric, DeviceReading>() }; group.readings.set(sample.metric, sample); groups.set(id, group); }
  return [...groups.values()].filter(item => item.readings.has("weight")).sort((a, b) => b.recordedAt.localeCompare(a.recordedAt));
}
function periodReadings(samples: readonly DeviceReading[], metric: Metric, period: Period) { const days = period === "7 дней" ? 7 : period === "Месяц" ? 31 : period === "3 месяца" ? 92 : 366; const start = new Date(); start.setDate(start.getDate() - days); return samples.filter(item => item.metric === metric && Date.parse(item.recordedAt) >= start.getTime()).sort((a, b) => a.recordedAt.localeCompare(b.recordedAt)); }
function deltaOf(current: Measurement | undefined, previous: Measurement | undefined, metric: Metric) { const a = current?.readings.get(metric)?.value; const b = previous?.readings.get(metric)?.value; return a === undefined || b === undefined ? undefined : a - b; }
function changeText(delta: number | undefined, info: ScaleMetricInfo) { if (delta === undefined) return "Недостаточно данных"; if (Math.abs(delta) < 10 ** -(info.digits + 1)) return "Без изменений"; return `${delta > 0 ? "Больше на" : "Меньше на"} ${fmt(Math.abs(delta), info.digits)} ${info.unit}`; }
function sourceStatus(reading?: DeviceReading) { return !reading ? "Нет данных" : reading.origin === "mock" ? "Временный расчёт" : "Получено от устройства"; }

export function ScaleProfileScreen({ onBack }: { onBack: () => void }) {
  const connection = useSyncExternalStore(scale.subscribe, scale.getSnapshot, scale.getSnapshot);
  const sync = useSyncExternalStore(scaleSync.subscribe, scaleSync.getSnapshot, scaleSync.getSnapshot);
  const [route, setRoute] = useState<Route>({ name: "overview" });
  const [flowVisible, setFlowVisible] = useState(false);
  const [resultVisible, setResultVisible] = useState(false);
  const measurements = useMemo(() => makeMeasurements(sync.batch?.samples ?? []), [sync.batch]);
  const latest = measurements[0]; const previous = measurements[1];
  const back = () => setRoute({ name: "overview" });
  let content: React.ReactNode;
  if (route.name === "composition") content = <CompositionScreen latest={latest} previous={previous} onBack={back} onMetric={metric => setRoute({ name: "metric", metric })} onSegments={() => setRoute({ name: "segments" })} />;
  else if (route.name === "segments") content = <SegmentScreen measurement={latest} onBack={back} />;
  else if (route.name === "history") content = <HistoryScreen measurements={measurements} timeZone={sync.batch?.timeZone} onBack={back} />;
  else if (route.name === "device") content = <DeviceScreen onBack={back} />;
  else if (route.name === "metric") content = <MetricScreen metric={route.metric} samples={sync.batch?.samples ?? []} onBack={back} />;
  else content = <Overview connection={connection} sync={sync} latest={latest} previous={previous} timeZone={sync.batch?.timeZone} onBack={onBack} onMeasure={() => setFlowVisible(true)} onComposition={() => setRoute({ name: "composition" })} onSegments={() => setRoute({ name: "segments" })} onHistory={() => setRoute({ name: "history" })} onDevice={() => setRoute({ name: "device" })} />;
  return <>{content}<ScaleMeasurementFlow visible={flowVisible} previousWeight={latest?.readings.get("weight")?.value} onClose={() => setFlowVisible(false)} onComplete={() => { setFlowVisible(false); setResultVisible(true); }} /><ResultSheet visible={resultVisible} latest={measurements[0]} previousWeight={measurements[1]?.readings.get("weight")?.value} onDetails={() => { setResultVisible(false); setRoute({ name: "composition" }); }} onClose={() => setResultVisible(false)} /></>;
}

function Overview({ connection, sync, latest, previous, timeZone, onBack, onMeasure, onComposition, onSegments, onHistory, onDevice }: { connection: ReturnType<typeof scale.getSnapshot>; sync: ReturnType<typeof scaleSync.getSnapshot>; latest?: Measurement; previous?: Measurement; timeZone?: string; onBack: () => void; onMeasure: () => void; onComposition: () => void; onSegments: () => void; onHistory: () => void; onDevice: () => void }) {
  const connected = connection.phase === "connected"; const selected = connection.devices.find(item => item.id === connection.selectedDeviceId); const weight = latest?.readings.get("weight"); const delta = deltaOf(latest, previous, "weight");
  return <Page title="Умные весы" subtitle="Вес, состав тела и динамика" onBack={onBack}>
    <AxReveal><AxCard style={styles.deviceHero}><View style={styles.deviceTop}><View style={[styles.deviceIcon, connected && styles.deviceIconOnline]}><Ionicons name="scale-outline" size={25} color={connected ? axColors.green : axColors.muted} /></View><View style={styles.flex}><Text maxFontSizeMultiplier={1.3} style={styles.deviceName}>{selected?.name ?? sync.batch?.device.name ?? "AxMed Scale"}</Text><Text maxFontSizeMultiplier={1.3} style={styles.deviceStatus}>{connected ? "Подключены и готовы" : weight ? "Доступны сохранённые данные" : "Устройство не подключено"}</Text></View><AxBadge label={connected ? "Онлайн" : "Оффлайн"} tone={connected ? "success" : "neutral"} /></View><View style={styles.deviceMetaRow}><DeviceMeta icon="bluetooth-outline" label="Bluetooth" value={connected ? "Активен" : "Нет связи"} /><DeviceMeta icon="time-outline" label="Последнее" value={weight ? dateLabel(weight.recordedAt, timeZone) : "Нет данных"} /></View></AxCard></AxReveal>
    <AxReveal delay={45}><AxCard style={styles.weightHero}><View style={styles.weightTop}><View><Text maxFontSizeMultiplier={1.3} style={styles.eyebrow}>РЕАЛЬНЫЙ ВЕС</Text><Text maxFontSizeMultiplier={1.3} style={styles.weightValue}>{fmt(weight?.value, 2)} <Text maxFontSizeMultiplier={1.3} style={styles.weightUnit}>{weight ? "кг" : ""}</Text></Text></View><View style={styles.realBadge}><Ionicons name="radio-button-on" size={13} color="#FFFFFF" /><Text maxFontSizeMultiplier={1.3} style={styles.realText}>С весов</Text></View></View><View style={styles.weightChange}><Ionicons name={delta === undefined || delta === 0 ? "remove" : delta > 0 ? "arrow-up" : "arrow-down"} size={16} color={axColors.blue} /><View style={styles.flex}><Text maxFontSizeMultiplier={1.3} style={styles.weightChangeValue}>{delta === undefined ? "Нет сравнения" : `${delta > 0 ? "+" : ""}${fmt(delta, 2)} кг`}</Text><Text maxFontSizeMultiplier={1.3} style={styles.weightChangeLabel}>К прошлому измерению · нейтральная динамика</Text></View></View><AxButton label={connected ? "Измерить" : "Найти и измерить"} icon="scale-outline" onPress={onMeasure} /></AxCard></AxReveal>
    <SectionTitle title="Данные весов" subtitle="Все действия доступны из одного места" /><View style={styles.actionGrid}><ActionCard icon="body-outline" title="Состав тела" subtitle="Все показатели" color={axColors.green} soft={axColors.greenSoft} onPress={onComposition} /><ActionCard icon="accessibility-outline" title="Сегменты" subtitle="Руки, ноги, корпус" color={axColors.purple} soft={axColors.purpleSoft} onPress={onSegments} /><ActionCard icon="time-outline" title="История" subtitle="Все измерения" color={axColors.blue} soft={axColors.blueSoft} onPress={onHistory} /><ActionCard icon="settings-outline" title="Устройство" subtitle="Подключение" color={axColors.amber} soft={axColors.amberSoft} onPress={onDevice} /></View>
    <Comparison latest={latest} previous={previous} /><View style={styles.lefu}><View style={styles.lefuIcon}><Ionicons name="flask-outline" size={20} color={axColors.amber} /></View><View style={styles.flex}><Text maxFontSizeMultiplier={1.3} style={styles.lefuTitle}>LEFU-анализ ожидает одобрения</Text><Text maxFontSizeMultiplier={1.3} style={styles.lefuText}>Вес всегда берётся с устройства. Временный состав отмечается бейджем «Демо» на каждой карточке.</Text></View></View>
  </Page>;
}

function CompositionScreen({ latest, previous, onBack, onMetric, onSegments }: { latest?: Measurement; previous?: Measurement; onBack: () => void; onMetric: (metric: Metric) => void; onSegments: () => void }) {
  const info = metricByName.get("weight")!; const weight = latest?.readings.get("weight");
  return <Page title="Состав тела" subtitle="Реальные и расчётные показатели" onBack={onBack}><AxCard onPress={() => onMetric("weight")} accessibilityLabel="Динамика веса" style={styles.realWeight}><View style={[styles.largeIcon, { backgroundColor: info.soft }]}><Ionicons name={info.icon} size={24} color={info.color} /></View><View style={styles.flex}><View style={styles.realTitle}><Text maxFontSizeMultiplier={1.3} style={styles.cardTitle}>Вес</Text><AxBadge label="Реальный" tone="success" /></View><Text maxFontSizeMultiplier={1.3} style={styles.realValue}>{fmt(weight?.value, 2)} <Text maxFontSizeMultiplier={1.3} style={styles.unit}>кг</Text></Text><Text maxFontSizeMultiplier={1.3} style={styles.muted}>{weight ? "Получено непосредственно от весов" : "Нет измерений"}</Text></View><Ionicons name="chevron-forward" size={19} color={axColors.muted} /></AxCard><SectionTitle title="Показатели" subtitle="Нажмите карточку, чтобы увидеть динамику" /><View style={styles.metricGrid}>{metricCatalog.filter(item => item.metric !== "weight").map((item, index) => <AxReveal key={item.metric} delay={index * 30} style={styles.metricReveal}><MetricTile info={item} reading={latest?.readings.get(item.metric)} delta={deltaOf(latest, previous, item.metric)} onPress={() => onMetric(item.metric)} /></AxReveal>)}</View><AxCard onPress={onSegments} accessibilityLabel="Сегментный анализ" tone="accent" style={styles.segmentLink}><View style={styles.segmentLinkIcon}><Ionicons name="accessibility-outline" size={24} color={axColors.green} /></View><View style={styles.flex}><Text maxFontSizeMultiplier={1.3} style={styles.cardTitle}>Сегментный анализ</Text><Text maxFontSizeMultiplier={1.3} style={styles.muted}>Мышцы и жир для рук, ног и корпуса</Text></View><Ionicons name="chevron-forward" size={20} color={axColors.green} /></AxCard><Disclaimer /></Page>;
}

function SegmentScreen({ measurement, onBack }: { measurement?: Measurement; onBack: () => void }) {
  const [selected, setSelected] = useState<BodySegmentKey>("trunk"); const [sheet, setSheet] = useState(false); const item = segmentCatalog.find(value => value.key === selected)!; const muscle = measurement?.readings.get(item.muscle); const fat = measurement?.readings.get(item.fat); const select = (key: BodySegmentKey) => { setSelected(key); setSheet(true); };
  return <><Page title="Сегментный анализ" subtitle="Руки, ноги и корпус" onBack={onBack}><AxCard style={styles.bodyCard}><View style={styles.bodyHeader}><View><Text maxFontSizeMultiplier={1.3} style={styles.cardTitle}>Выберите область</Text><Text maxFontSizeMultiplier={1.3} style={styles.muted}>Коснитесь сегмента на схеме</Text></View><AxBadge label="Демо" tone="warning" icon="flask-outline" /></View><ScaleBodyDiagram selected={selected} onSelect={select} /><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.chips}>{segmentCatalog.map(value => <AxFilterChip key={value.key} label={value.label} selected={selected === value.key} onPress={() => select(value.key)} />)}</ScrollView></AxCard><AxPressable accessibilityLabel={item.label} onPress={() => setSheet(true)} style={styles.selectedSegment}><View style={styles.selectedIcon}><Ionicons name="body-outline" size={21} color={axColors.green} /></View><View style={styles.flex}><Text maxFontSizeMultiplier={1.3} style={styles.selectedTitle}>{item.label}</Text><Text maxFontSizeMultiplier={1.3} style={styles.muted}>Расчётные значения</Text></View><View style={styles.selectedValues}><Text maxFontSizeMultiplier={1.3} style={styles.muscle}>{fmt(muscle?.value, 2)} кг</Text><Text maxFontSizeMultiplier={1.3} style={styles.fat}>{fmt(fat?.value, 1)}%</Text></View><Ionicons name="chevron-forward" size={18} color={axColors.muted} /></AxPressable><Disclaimer text="Сегментные показатели сейчас демонстрационные. Схема не является медицинским изображением." /></Page><AxBottomSheet visible={sheet} title={item.label} subtitle="Расчётный сегментный состав" onClose={() => setSheet(false)}><View style={styles.sheetValues}><SheetValue icon="barbell-outline" label="Мышечная масса" value={`${fmt(muscle?.value, 2)} кг`} color={axColors.blue} soft={axColors.blueSoft} /><SheetValue icon="flame-outline" label="Процент жира" value={`${fmt(fat?.value, 1)}%`} color={axColors.coral} soft={axColors.coralSoft} /></View><View style={styles.demoNote}><Ionicons name="flask-outline" size={18} color={axColors.amber} /><Text maxFontSizeMultiplier={1.3} style={styles.demoText}>Демо-расчёт заменится реальными данными после одобрения LEFU.</Text></View><AxButton label="Готово" onPress={() => setSheet(false)} /></AxBottomSheet></>;
}

function MetricScreen({ metric, samples, onBack }: { metric: Metric; samples: DeviceReading[]; onBack: () => void }) {
  const [period, setPeriod] = useState<Period>("Месяц"); const info = metricByName.get(metric) ?? metricByName.get("weight")!; const readings = useMemo(() => periodReadings(samples, metric, period), [metric, period, samples]); const latest = readings.at(-1); const delta = latest && readings[0] ? latest.value - readings[0].value : undefined; const values = readings.map(item => item.value); const average = values.length ? values.reduce((sum, value) => sum + value, 0) / values.length : undefined;
  return <Page title={info.label} subtitle="Динамика показателя" onBack={onBack}><AxCard style={styles.metricHero}><View style={[styles.largeIcon, { backgroundColor: info.soft }]}><Ionicons name={info.icon} size={25} color={info.color} /></View><Text maxFontSizeMultiplier={1.3} style={styles.heroValue}>{fmt(latest?.value, info.digits)} <Text maxFontSizeMultiplier={1.3} style={styles.heroUnit}>{latest ? info.unit : ""}</Text></Text><Text maxFontSizeMultiplier={1.3} style={[styles.heroStatus, { color: info.color }]}>{sourceStatus(latest)}</Text><Text maxFontSizeMultiplier={1.3} style={styles.heroDate}>{latest ? dateLabel(latest.recordedAt) : "Измерений пока нет"}</Text>{latest?.origin === "mock" ? <AxBadge label="Демо" tone="warning" icon="flask-outline" /> : null}</AxCard><AxSegmentedControl value={period} options={periodOptions} onChange={setPeriod} /><AxCard style={styles.chartCard}><View style={styles.chartHeader}><View><Text maxFontSizeMultiplier={1.3} style={styles.chartTitle}>Динамика</Text><Text maxFontSizeMultiplier={1.3} style={styles.muted}>{period}</Text></View><View style={styles.deltaBox}><Text maxFontSizeMultiplier={1.3} style={styles.deltaLabel}>Изменение</Text><Text maxFontSizeMultiplier={1.3} style={[styles.deltaValue, { color: info.color }]}>{delta === undefined ? "—" : `${delta > 0 ? "+" : ""}${fmt(delta, info.digits)} ${info.unit}`}</Text></View></View><MetricChart readings={readings} color={info.color} digits={info.digits} unit={info.unit} /><View style={styles.stats}><Stat label="Минимум" value={values.length ? Math.min(...values) : undefined} info={info} /><Stat label="Среднее" value={average} info={info} /><Stat label="Максимум" value={values.length ? Math.max(...values) : undefined} info={info} /></View></AxCard><View style={styles.info}><View style={[styles.infoIcon, { backgroundColor: info.soft }]}><Ionicons name="information-circle-outline" size={18} color={info.color} /></View><View style={styles.flex}><Text maxFontSizeMultiplier={1.3} style={styles.infoTitle}>Что показывает показатель</Text><Text maxFontSizeMultiplier={1.3} style={styles.infoText}>{info.description}</Text></View></View><SectionTitle title="Последние значения" subtitle={`${readings.length} записей за период`} />{readings.length ? <View style={styles.readingList}>{[...readings].reverse().slice(0, 10).map(reading => <View key={`${reading.sourceRecordId}:${reading.recordedAt}`} style={styles.readingRow}><View><Text maxFontSizeMultiplier={1.3} style={styles.readingDate}>{dateLabel(reading.recordedAt)}</Text><Text maxFontSizeMultiplier={1.3} style={styles.readingSource}>{reading.origin === "mock" ? "Демо-расчёт" : "AxMed Scale"}</Text></View><Text maxFontSizeMultiplier={1.3} style={styles.readingValue}>{fmt(reading.value, info.digits)} {info.unit}</Text></View>)}</View> : <Empty title="Нет данных за период" text="Выберите другой период или выполните измерение." />}<Disclaimer /></Page>;
}

function HistoryScreen({ measurements, timeZone, onBack }: { measurements: Measurement[]; timeZone?: string; onBack: () => void }) {
  const [selected, setSelected] = useState<Measurement>();
  return <><Page title="История весов" subtitle="Сохранённые измерения" onBack={onBack}><View style={styles.historyHero}><View><Text maxFontSizeMultiplier={1.3} style={styles.historyCount}>{measurements.length}</Text><Text maxFontSizeMultiplier={1.3} style={styles.historyLabel}>измерений в аккаунте</Text></View><View style={styles.historyIcon}><Ionicons name="time-outline" size={26} color="#FFFFFF" /></View></View>{measurements.length ? <View style={styles.historyList}>{measurements.map((measurement, index) => <AxReveal key={measurement.id} delay={Math.min(index, 8) * 30}><HistoryRow measurement={measurement} previous={measurements[index + 1]} timeZone={timeZone} onPress={() => setSelected(measurement)} /></AxReveal>)}</View> : <Empty title="Пока нет измерений" text="Подключите весы и выполните первое измерение." />}</Page><MeasurementSheet measurement={selected} previous={selected ? measurements[measurements.findIndex(value => value.id === selected.id) + 1] : undefined} onClose={() => setSelected(undefined)} /></>;
}

function DeviceScreen({ onBack }: { onBack: () => void }) {
  const connection = useSyncExternalStore(scale.subscribe, scale.getSnapshot, scale.getSnapshot); const connected = connection.phase === "connected"; const searching = connection.phase === "scanning" || connection.phase === "requestingPermission"; const selected = connection.devices.find(item => item.id === connection.selectedDeviceId);
  return <Page title="Управление весами" subtitle="Подключение и Bluetooth" onBack={onBack}><AxCard style={styles.manage}><View style={[styles.manageIcon, connected && { backgroundColor: axColors.greenSoft }]}><Ionicons name="scale-outline" size={28} color={connected ? axColors.green : axColors.muted} /></View><Text maxFontSizeMultiplier={1.3} style={styles.manageTitle}>{selected?.name ?? "AxMed Scale"}</Text><Text maxFontSizeMultiplier={1.3} style={styles.manageStatus}>{connected ? "Подключены" : searching ? "Идёт поиск…" : "Не подключены"}</Text><AxBadge label={connected ? "Bluetooth активен" : "Нет соединения"} tone={connected ? "success" : "neutral"} /></AxCard>{!connected && connection.devices.map(device => <AxPressable key={device.id} accessibilityLabel={`Подключить ${device.name}`} onPress={() => void deviceBindings.connect("scale", device.id)} style={styles.found}><View style={styles.foundIcon}><Ionicons name="bluetooth" size={20} color={axColors.green} /></View><View style={styles.flex}><Text maxFontSizeMultiplier={1.3} style={styles.foundName}>{device.name}</Text><Text maxFontSizeMultiplier={1.3} style={styles.muted}>Сигнал {device.rssi} dBm</Text></View><Text maxFontSizeMultiplier={1.3} style={styles.foundAction}>Подключить</Text></AxPressable>)}{connection.errorCode ? <View style={styles.error}><Ionicons name="alert-circle-outline" size={19} color={axColors.danger} /><Text maxFontSizeMultiplier={1.3} style={styles.errorText}>{connection.errorCode === "simulatorUnsupported" ? "Bluetooth недоступен в симуляторе. Используйте реальный iPhone для измерения." : connection.errorCode === "bluetoothOff" ? "Включите Bluetooth и повторите." : "Не удалось подключить весы."}</Text></View> : null}<AxButton label={connected ? "Отключить весы" : searching ? "Ищем весы…" : "Найти весы"} icon={connected ? "close-circle-outline" : "bluetooth-outline"} variant={connected ? "outline" : "primary"} disabled={searching} onPress={() => connected ? void deviceBindings.disconnect("scale") : void deviceBindings.scan("scale")} /><Disclaimer text="AxMed подключается к весам только во время поиска и измерения." /></Page>;
}

function ResultSheet({ visible, latest, previousWeight, onDetails, onClose }: { visible: boolean; latest?: Measurement; previousWeight?: number; onDetails: () => void; onClose: () => void }) { const weight = latest?.readings.get("weight"); const delta = weight && previousWeight !== undefined ? weight.value - previousWeight : undefined; return <AxBottomSheet visible={visible} title="Измерение сохранено" subtitle="Новые данные добавлены в историю" onClose={onClose}><View style={styles.result}><View style={styles.resultCheck}><Ionicons name="checkmark" size={26} color={axColors.onAccent} /></View><Text maxFontSizeMultiplier={1.3} style={styles.resultWeight}>{fmt(weight?.value, 2)} <Text maxFontSizeMultiplier={1.3} style={styles.resultUnit}>кг</Text></Text><Text maxFontSizeMultiplier={1.3} style={styles.resultDelta}>{delta === undefined ? "Первое измерение" : `${delta > 0 ? "+" : ""}${fmt(delta, 2)} кг к предыдущему`}</Text></View><View style={styles.resultGrid}><ResultMetric label="Жир" reading={latest?.readings.get("bodyFatPercentage")} unit="%" /><ResultMetric label="Мышцы" reading={latest?.readings.get("muscleMass")} unit="кг" /><ResultMetric label="Вода" reading={latest?.readings.get("bodyWaterPercentage")} unit="%" /><ResultMetric label="Оценка" reading={latest?.readings.get("bodyScore")} unit="/100" /></View><View style={styles.sheetActions}><AxButton label="Подробнее" icon="analytics-outline" onPress={onDetails} /><AxButton label="Готово" variant="secondary" onPress={onClose} /></View></AxBottomSheet>; }
function MeasurementSheet({ measurement, previous, onClose }: { measurement?: Measurement; previous?: Measurement; onClose: () => void }) { const weight = measurement?.readings.get("weight"); return <AxBottomSheet visible={Boolean(measurement)} title="Измерение" subtitle={measurement ? dateLabel(measurement.recordedAt) : undefined} onClose={onClose}><Text maxFontSizeMultiplier={1.3} style={styles.sheetWeight}>{fmt(weight?.value, 2)} <Text maxFontSizeMultiplier={1.3} style={styles.sheetWeightUnit}>кг</Text></Text><Text maxFontSizeMultiplier={1.3} style={styles.sheetDelta}>{changeText(deltaOf(measurement, previous, "weight"), metricByName.get("weight")!)}</Text><View style={styles.sheetValues}>{(["bodyFatPercentage", "muscleMass", "bodyWaterPercentage", "bodyScore"] as Metric[]).map(metric => { const info = metricByName.get(metric)!; return <SheetValue key={metric} icon={info.icon} label={info.shortLabel} value={`${fmt(measurement?.readings.get(metric)?.value, info.digits)} ${info.unit}`} color={info.color} soft={info.soft} />; })}</View><Disclaimer text="Изменения показаны нейтрально и не являются оценкой здоровья." /><AxButton label="Готово" onPress={onClose} /></AxBottomSheet>; }

function Comparison({ latest, previous }: { latest?: Measurement; previous?: Measurement }) { if (!latest || !previous) return <AxCard style={styles.compareEmpty}><View style={styles.compareEmptyIcon}><Ionicons name="git-compare-outline" size={21} color={axColors.blue} /></View><View style={styles.flex}><Text maxFontSizeMultiplier={1.3} style={styles.cardTitle}>Сравнение измерений</Text><Text maxFontSizeMultiplier={1.3} style={styles.muted}>Нужны минимум два измерения.</Text></View></AxCard>; return <View style={styles.compare}><View style={styles.compareHeader}><View><Text maxFontSizeMultiplier={1.3} style={styles.cardTitle}>Что изменилось</Text><Text maxFontSizeMultiplier={1.3} style={styles.muted}>Два последних измерения · без оценки «хорошо/плохо»</Text></View><Ionicons name="git-compare-outline" size={22} color={axColors.blue} /></View>{(["weight", "bodyFatPercentage", "muscleMass", "bodyWaterPercentage"] as Metric[]).map(metric => { const info = metricByName.get(metric)!; const delta = deltaOf(latest, previous, metric); return <View key={metric} style={styles.compareRow}><View style={[styles.compareIcon, { backgroundColor: info.soft }]}><Ionicons name={info.icon} size={16} color={info.color} /></View><Text maxFontSizeMultiplier={1.3} style={styles.compareLabel}>{info.shortLabel}</Text><View style={[styles.change, { backgroundColor: delta === undefined || delta === 0 ? axColors.surfaceMuted : delta > 0 ? axColors.coralSoft : axColors.blueSoft }]}><Ionicons name={delta === undefined || delta === 0 ? "remove" : delta > 0 ? "arrow-up" : "arrow-down"} size={12} color={delta === undefined || delta === 0 ? axColors.muted : delta > 0 ? axColors.coral : axColors.blue} /><Text maxFontSizeMultiplier={1.3} numberOfLines={1} style={styles.changeText}>{changeText(delta, info)}</Text></View></View>; })}</View>; }
function MetricTile({ info, reading, delta, onPress }: { info: ScaleMetricInfo; reading?: DeviceReading; delta?: number; onPress: () => void }) { return <AxPressable accessibilityLabel={`${info.label}: ${fmt(reading?.value, info.digits)}`} onPress={onPress} style={styles.metricTile}><View style={styles.metricTop}><View style={[styles.metricIcon, { backgroundColor: info.soft }]}><Ionicons name={info.icon} size={19} color={info.color} /></View>{reading?.origin === "mock" ? <AxBadge label="Демо" tone="warning" /> : <Ionicons name="chevron-forward" size={16} color={axColors.muted} />}</View><Text maxFontSizeMultiplier={1.3} style={styles.metricLabel}>{info.shortLabel}</Text><Text maxFontSizeMultiplier={1.3} numberOfLines={1} adjustsFontSizeToFit style={styles.metricValue}>{fmt(reading?.value, info.digits)} <Text maxFontSizeMultiplier={1.3} style={styles.unit}>{reading ? info.unit : ""}</Text></Text><Text maxFontSizeMultiplier={1.3} numberOfLines={1} style={styles.metricChange}>{delta === undefined ? sourceStatus(reading) : changeText(delta, info)}</Text></AxPressable>; }
function HistoryRow({ measurement, previous, timeZone, onPress }: { measurement: Measurement; previous?: Measurement; timeZone?: string; onPress: () => void }) { const weight = measurement.readings.get("weight"); const fat = measurement.readings.get("bodyFatPercentage"); const muscle = measurement.readings.get("muscleMass"); const delta = deltaOf(measurement, previous, "weight"); return <AxPressable accessibilityLabel={`Измерение ${dateLabel(measurement.recordedAt, timeZone)}`} onPress={onPress} style={styles.historyRow}><View style={styles.calendar}><Ionicons name="calendar-clear-outline" size={19} color={axColors.green} /></View><View style={styles.flex}><View style={styles.historyTop}><Text maxFontSizeMultiplier={1.3} style={styles.historyWeight}>{fmt(weight?.value, 2)} кг</Text><Text maxFontSizeMultiplier={1.3} style={styles.historyDate}>{dateLabel(measurement.recordedAt, timeZone)}</Text></View><View style={styles.historyMetrics}>{fat ? <Text maxFontSizeMultiplier={1.3} style={styles.historyMetric}>Жир <Text maxFontSizeMultiplier={1.3} style={styles.historyMetricStrong}>{fmt(fat.value, 1)}%</Text></Text> : null}{muscle ? <Text maxFontSizeMultiplier={1.3} style={styles.historyMetric}>Мышцы <Text maxFontSizeMultiplier={1.3} style={styles.historyMetricStrong}>{fmt(muscle.value, 1)} кг</Text></Text> : null}{delta !== undefined ? <Text maxFontSizeMultiplier={1.3} style={styles.historyMetric}>Δ <Text maxFontSizeMultiplier={1.3} style={styles.historyMetricStrong}>{delta > 0 ? "+" : ""}{fmt(delta, 2)} кг</Text></Text> : null}</View></View><Ionicons name="chevron-forward" size={18} color={axColors.muted} /></AxPressable>; }

function MetricChart({ readings, color, digits, unit }: { readings: DeviceReading[]; color: string; digits: number; unit: string }) { if (!readings.length) return <View style={styles.chartEmpty}><Ionicons name="analytics-outline" size={27} color={axColors.muted} /><Text maxFontSizeMultiplier={1.3} style={styles.muted}>Нет данных для графика</Text></View>; return <InteractiveChart readings={readings} color={color} digits={digits} unit={unit} />; }
function InteractiveChart({ readings, color, digits, unit }: { readings: DeviceReading[]; color: string; digits: number; unit: string }) {
  const display = readings.length <= 32 ? readings : readings.filter((_, index) => index % Math.ceil(readings.length / 32) === 0 || index === readings.length - 1); const [selected, setSelected] = useState(display.length - 1); const [width, setWidth] = useState(320); const draw = useSharedValue(0); const reduce = useAxReducedMotion(); const key = `${display.length}:${display[0]?.recordedAt}:${display.at(-1)?.recordedAt}:${display.at(-1)?.value}`;
  useEffect(() => { setSelected(display.length - 1); draw.value = 0; draw.value = withTiming(1, { duration: reduce ? 0 : 360, easing: Easing.out(Easing.cubic) }); }, [display.length, draw, key, reduce]);
  const values = display.map(item => item.value); const min = Math.min(...values); const max = Math.max(...values); const range = Math.max(1, max - min); const points = display.map((item, index) => ({ x: display.length === 1 ? 160 : 18 + index * (284 / (display.length - 1)), y: 126 - ((item.value - min) / range) * 86 })); const path = points.map((point, index) => `${index ? "L" : "M"} ${point.x.toFixed(1)} ${point.y.toFixed(1)}`).join(" "); const props = useAnimatedProps(() => ({ strokeDashoffset: 1000 * (1 - draw.value), opacity: draw.value })); const update = (event: GestureResponderEvent) => setSelected(Math.max(0, Math.min(display.length - 1, Math.round((event.nativeEvent.locationX / width) * (display.length - 1))))); const point = points[selected]; const reading = display[selected];
  return <TabSwipeGuard style={styles.chart} onLayout={(event: LayoutChangeEvent) => setWidth(event.nativeEvent.layout.width)} onTouchStart={update} onTouchMove={update} accessibilityRole="image" accessibilityLabel={`График ${display.length} измерений`}>{point && reading ? <View pointerEvents="none" style={[styles.tooltip, { left: Math.max(6, Math.min(width - 116, point.x / 320 * width - 54)) }]}><Text maxFontSizeMultiplier={1.3} style={styles.tooltipValue}>{fmt(reading.value, digits)} {unit}</Text><Text maxFontSizeMultiplier={1.3} style={styles.tooltipDate}>{dateLabel(reading.recordedAt)}</Text></View> : null}<Svg width="100%" height="160" viewBox="0 0 320 160"><Path d="M18 40 H302 M18 83 H302 M18 126 H302" stroke={axColors.line} strokeWidth="1" /><AnimatedPath animatedProps={props} d={path} stroke={color} strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" strokeDasharray="1000 1000" fill="none" />{points.map((item, index) => <Circle key={`${item.x}:${index}`} cx={item.x} cy={item.y} r={index === selected ? 5 : 2.5} fill={axColors.surface} stroke={color} strokeWidth={index === selected ? 3 : 2} />)}</Svg></TabSwipeGuard>;
}

function Page({ title, subtitle, onBack, children }: { title: string; subtitle: string; onBack: () => void; children: React.ReactNode }) { return <View style={styles.screen}><ScrollView contentContainerStyle={styles.scroll} showsVerticalScrollIndicator={false}><View style={styles.header}><AxPressable accessibilityLabel="Назад" onPress={onBack} style={styles.back}><Ionicons name="chevron-back" size={23} color={axColors.ink} /></AxPressable><View style={styles.flex}><Text maxFontSizeMultiplier={1.3} accessibilityRole="header" style={styles.pageTitle}>{title}</Text><Text maxFontSizeMultiplier={1.3} style={styles.pageSubtitle}>{subtitle}</Text></View></View>{children}</ScrollView></View>; }
function SectionTitle({ title, subtitle }: { title: string; subtitle: string }) { return <View style={styles.section}><Text maxFontSizeMultiplier={1.3} style={styles.sectionTitle}>{title}</Text><Text maxFontSizeMultiplier={1.3} style={styles.sectionSubtitle}>{subtitle}</Text></View>; }
function DeviceMeta({ icon, label, value }: { icon: IconName; label: string; value: string }) { return <View style={styles.deviceMeta}><Ionicons name={icon} size={16} color={axColors.green} /><View style={styles.flex}><Text maxFontSizeMultiplier={1.3} style={styles.deviceMetaValue} numberOfLines={1}>{value}</Text><Text maxFontSizeMultiplier={1.3} style={styles.deviceMetaLabel}>{label}</Text></View></View>; }
function ActionCard({ icon, title, subtitle, color, soft, onPress }: { icon: IconName; title: string; subtitle: string; color: string; soft: string; onPress: () => void }) { return <AxPressable accessibilityLabel={title} onPress={onPress} style={styles.action}><View style={[styles.actionIcon, { backgroundColor: soft }]}><Ionicons name={icon} size={21} color={color} /></View><Text maxFontSizeMultiplier={1.3} style={styles.actionTitle}>{title}</Text><Text maxFontSizeMultiplier={1.3} style={styles.actionSubtitle}>{subtitle}</Text><Ionicons name="chevron-forward" size={16} color={axColors.muted} style={styles.actionChevron} /></AxPressable>; }
function ResultMetric({ label, reading, unit }: { label: string; reading?: DeviceReading; unit: string }) { return <View style={styles.resultMetric}><View style={styles.resultMetricTop}><Text maxFontSizeMultiplier={1.3} style={styles.resultMetricLabel}>{label}</Text>{reading?.origin === "mock" ? <Text maxFontSizeMultiplier={1.3} style={styles.resultDemo}>Демо</Text> : null}</View><Text maxFontSizeMultiplier={1.3} style={styles.resultMetricValue}>{fmt(reading?.value, 1)} <Text maxFontSizeMultiplier={1.3} style={styles.resultMetricUnit}>{unit}</Text></Text></View>; }
function SheetValue({ icon, label, value, color, soft }: { icon: IconName; label: string; value: string; color: string; soft: string }) { return <View style={styles.sheetValue}><View style={[styles.sheetValueIcon, { backgroundColor: soft }]}><Ionicons name={icon} size={18} color={color} /></View><View style={styles.flex}><Text maxFontSizeMultiplier={1.3} style={styles.sheetValueLabel}>{label}</Text><Text maxFontSizeMultiplier={1.3} style={styles.sheetValueText}>{value}</Text></View></View>; }
function Stat({ label, value, info }: { label: string; value?: number; info: ScaleMetricInfo }) { return <View style={styles.stat}><Text maxFontSizeMultiplier={1.3} style={styles.statLabel}>{label}</Text><Text maxFontSizeMultiplier={1.3} style={styles.statValue}>{fmt(value, info.digits)} <Text maxFontSizeMultiplier={1.3} style={styles.statUnit}>{value === undefined ? "" : info.unit}</Text></Text></View>; }
function Empty({ title, text }: { title: string; text: string }) { return <AxCard style={styles.empty}><View style={styles.emptyIcon}><Ionicons name="analytics-outline" size={27} color={axColors.green} /></View><Text maxFontSizeMultiplier={1.3} style={styles.emptyTitle}>{title}</Text><Text maxFontSizeMultiplier={1.3} style={styles.emptyText}>{text}</Text></AxCard>; }
function Disclaimer({ text = "Показатели предназначены для наблюдения за динамикой и не являются медицинским заключением." }: { text?: string }) { return <View style={styles.disclaimer}><Ionicons name="shield-checkmark-outline" size={19} color={axColors.green} /><Text maxFontSizeMultiplier={1.3} style={styles.disclaimerText}>{text}</Text></View>; }

