  compare:{borderRadius:22,padding:15,backgroundColor:axColors.surface,borderWidth:1,borderColor:axColors.line,marginBottom:14},compareEmpty:{flexDirection:"row",alignItems:"center",gap:10,marginBottom:14},compareEmptyIcon:{width:42,height:42,borderRadius:14,backgroundColor:axColors.blueSoft,alignItems:"center",justifyContent:"center"},compareHeader:{flexDirection:"row",justifyContent:"space-between",alignItems:"flex-start",marginBottom:8},compareRow:{minHeight:52,borderTopWidth:1,borderTopColor:axColors.line,flexDirection:"row",alignItems:"center",gap:8},compareIcon:{width:31,height:31,borderRadius:10,alignItems:"center",justifyContent:"center"},compareLabel:{flex:1,color:axColors.text,fontSize:10,fontWeight:"700"},change:{maxWidth:"58%",minHeight:28,borderRadius:10,paddingHorizontal:7,flexDirection:"row",alignItems:"center",gap:4},changeText:{flexShrink:1,color:axColors.text,fontSize:8,fontWeight:"700"},
